<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { t,uiLanguage } from '../lib/uiLocale'
const props=defineProps<{snapshot:any}>();
const updateAvailable=computed(()=>props.snapshot.update?.verified===true&&props.snapshot.update?.status==='available')
const updateCurrent=computed(()=>props.snapshot.update?.verified===true&&props.snapshot.update?.status==='current')
const emit=defineEmits(['close','updated']);const error=ref(''),busy=ref(false)
const panel=ref<HTMLElement>(),previousFocus=document.activeElement as HTMLElement|null
onMounted(()=>panel.value?.querySelector<HTMLButtonElement>('button')?.focus())
onUnmounted(()=>previousFocus?.isConnected&&previousFocus.focus({preventScroll:true}))
function trapFocus(event:KeyboardEvent){if(event.key!=='Tab')return;const buttons=[...panel.value!.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')];if(!buttons.length)return;const first=buttons[0],last=buttons.at(-1)!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
async function act(key:string,action:string){busy.value=true;error.value='';try{emit('updated',await window.desktopAPI.noticeAction(key,action))}catch(e:any){error.value=e?.message||t('暂时无法完成，请稍后重试。')}finally{busy.value=false}}
async function refresh(){busy.value=true;error.value='';try{emit('updated',await window.desktopAPI.refreshNotices())}catch(e:any){error.value=e?.message||t('通知同步未完成，稍后自动重试。')}finally{busy.value=false}}
function date(value:string){return new Date(value).toLocaleString(uiLanguage.value==='en'?'en-US':'zh-CN')}
</script>
<template><div class="notices-backdrop" @click.self="emit('close')" @keydown.esc.stop="emit('close')"><section ref="panel" class="notices-panel" @keydown="trapFocus" role="dialog" aria-modal="true" :aria-label="t('消息中心')"><header><div><h2>{{t('消息中心')}}</h2><p>{{t('最新版本与通知')}}</p></div><button class="icon-button" @click="emit('close')" :aria-label="t('关闭')">×</button></header><div class="notice-list">
 <p v-if="error||snapshot.error" class="notice-error" role="alert">{{error||snapshot.error}}</p>
 <article v-if="updateAvailable" class="notice-item update-item"><small>{{t('版本更新提醒')}}</small><h3>{{t('发现新版本 {0}',snapshot.update.latestVersion)}}</h3><p>{{snapshot.update.notes}}</p><footer><span>{{t('当前')}} {{snapshot.update.currentVersion}}</span><button :disabled="busy" @click="act('update:'+snapshot.update.latestVersion,'open')">{{t('前往官网更新')}}</button></footer></article>
 <article v-else class="notice-item version-status" role="status"><small>{{t('当前版本')}} {{snapshot.update?.currentVersion || '—'}}</small><h3>{{updateCurrent?t('已是当前最新版本'):snapshot.update?.verified && snapshot.update?.status==='ahead'?t('本机版本较新'):t('版本检查尚未完成')}}</h3><p v-if="updateCurrent && snapshot.update?.notes">{{snapshot.update.notes}}</p><p v-else-if="!updateCurrent">{{t('点击刷新核对官网最新版本。')}}</p></article>
 <article v-for="item in snapshot.notices||[]" :key="item.id+':'+item.revision" class="notice-item" :class="{unread:!item.dismissed}"><small>{{date(item.starts_at)}} <span v-if="!item.dismissed">· {{t('未读')}}</span></small><h3>{{item.title}}</h3><p>{{item.body}}</p><footer><button v-if="!item.dismissed" :disabled="busy" @click="act(item.id+':'+item.revision,'dismiss')">{{t('知道了')}}</button><span v-else>{{t('已确认')}}</span><button v-if="item.action!=='none' && (item.action!=='download' || updateAvailable)" :disabled="busy" @click="act(item.id+':'+item.revision,'open')">{{item.action==='download'?t('前往官网更新'):t('前往官网')}}</button></footer></article>
 <div v-if="!snapshot.notices?.length" class="notice-empty">{{t('暂时没有新通知')}}</div>
 </div><footer class="notice-bottom"><small>{{t('通知会自动同步')}}</small><button :disabled="busy" @click="refresh">{{busy?t('正在同步…'):t('刷新')}}</button></footer></section></div></template>
<style scoped>
.notices-backdrop{position:fixed;inset:0;background:#080c10c9;z-index:130;display:flex;align-items:center;justify-content:center;padding:24px}.notices-panel{width:min(560px,100%);max-height:85vh;display:flex;flex-direction:column;background:#191e24;color:var(--text);border:1px solid var(--border);border-radius:16px;box-shadow:0 24px 60px #0004;overflow:hidden}.notices-panel>header{display:flex;align-items:center;justify-content:space-between;padding:20px 22px;border-bottom:1px solid var(--border)}h2{margin:0;font-size:20px}header p{margin:5px 0 0;font-size:12px;color:var(--muted)}.notice-list{padding:18px;overflow:auto}.notice-item{background:#242a32;padding:16px;border:1px solid var(--border);border-radius:10px;margin-bottom:12px}.notice-item.unread,.update-item{border-color:var(--accent)}h3{font-size:15px;margin:8px 0;overflow-wrap:anywhere}.notice-item p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.65}.notice-item small,footer span{font-size:11px;color:var(--muted)}footer{display:flex;align-items:center;justify-content:space-between;gap:8px}.notices-panel button:not(.icon-button){border:0;background:var(--accent-soft);color:var(--text);padding:8px 12px;border-radius:7px;cursor:pointer}.notice-bottom{padding:14px 20px;border-top:1px solid var(--border);color:var(--muted)}.notice-empty{text-align:center;padding:60px 15px;color:var(--muted)}.notice-error{color:var(--danger,#e09987);font-size:12px}button:disabled{opacity:.6}
</style>
